import * as http from "node:http";
const srv = http.createServer((req, res) => {
  if (req.url === "/stream") { res.writeHead(200, { "Content-Type": "text/plain" }); res.write("a"); res.write("b"); res.end("c"); return; }
  res.writeHead(200, { "Transfer-Encoding": "chunked" }); res.end("x");
});
function main(): void {
  srv.listen(0, "127.0.0.1", async () => {
    const base = `http://127.0.0.1:${(srv.address() as any).port}`;
    const a = await fetch(base + "/");
    console.log(a.headers.get("transfer-encoding"), a.headers.get("content-length"), a.headers.has("date"), await a.text());
    const b = await fetch(base + "/stream");
    console.log(b.headers.get("transfer-encoding"), b.headers.get("content-length"), b.headers.has("date"), await b.text());
    srv.close();
  });
}
